1	import type { LiveViewHookSpec, ViewHookInternal } from "phoenix_live_view";
2	import type {
3	  ReadaloudHandleEvents,
4	  ReadaloudPushEvents,
5	  ReadaloudWindowEvents,
6	} from "./events";
7	
8	type EmptyPayload = undefined | Record<string, never>;
9	
10	type WindowEventDetail<K extends keyof ReadaloudWindowEvents> =
11	  ReadaloudWindowEvents[K] extends undefined
12	    ? []
13	    : [detail: ReadaloudWindowEvents[K]];
14	
15	type PushEventArgs<K extends keyof ReadaloudPushEvents> =
16	  ReadaloudPushEvents[K] extends EmptyPayload
17	    ? []
18	    : [payload: ReadaloudPushEvents[K]];
19	
20	export interface HookContext<
21	  TEl extends HTMLElement = HTMLElement,
22	  TDataset = Record<string, string | undefined>,
23	> {
24	  readonly el: TEl;
25	  readonly dataset: Readonly<TDataset>;
26	
27	  on<K extends keyof HTMLElementEventMap>(
28	    target: HTMLElement | Document,
29	    event: K,
30	    handler: (e: HTMLElementEventMap[K]) => void,
31	    opts?: AddEventListenerOptions,
32	  ): void;
33	  on<K extends keyof WindowEventMap>(
34	    target: Window,
35	    event: K,
36	    handler: (e: WindowEventMap[K]) => void,
37	    opts?: AddEventListenerOptions,
38	  ): void;
39	  on<K extends keyof ReadaloudWindowEvents>(
40	    target: Window,
41	    event: K,
42	    handler: ReadaloudWindowEvents[K] extends undefined
43	      ? () => void
44	      : (detail: ReadaloudWindowEvents[K]) => void,
45	  ): void;
46	
47	  dispatch<K extends keyof ReadaloudWindowEvents>(
48	    event: K,
49	    ...detail: WindowEventDetail<K>
50	  ): void;
51	
52	  pushEvent<K extends keyof ReadaloudPushEvents>(
53	    event: K,
54	    ...payload: PushEventArgs<K>
55	  ): void;
56	
57	  handleEvent<K extends keyof ReadaloudHandleEvents>(
58	    event: K,
59	    handler: (payload: ReadaloudHandleEvents[K]) => void,
60	  ): void;
61	
62	  onDestroy(fn: () => void): void;
63	}
64	
65	const READALOUD_EVENT_PREFIX_RE =
66	  /^(audio:|manual-scroll$|auto-scroll-|word-action$|toggle-pill$|chapter-bar-close$|readaloud:|phx:)/;
67	
68	function isReadaloudEvent(event: string): boolean {
69	  return READALOUD_EVENT_PREFIX_RE.test(event);
70	}
71	
72	export function defineHook<
73	  TEl extends HTMLElement = HTMLElement,
74	  TDataset = Record<string, string | undefined>,
75	>(setup: (ctx: HookContext<TEl, TDataset>) => void): LiveViewHookSpec {
76	  return {
77	    mounted(this: ViewHookInternal): void {
78	      const disposers: Array<() => void> = [];
79	      const lv = this;
80	
81	      const ctx: HookContext<TEl, TDataset> = {
82	        el: this.el as TEl,
83	        dataset: this.el.dataset as unknown as Readonly<TDataset>,
84	
85	        on(
86	          target: EventTarget,
87	          event: string,
88	          handler: (arg: unknown) => void,
89	          opts?: AddEventListenerOptions,
90	        ): void {
91	          if (target === window && isReadaloudEvent(event)) {
92	            const wrapped = (e: Event): void => {
93	              const detail = (e as CustomEvent).detail;
94	              handler(detail);
95	            };
96	            window.addEventListener(event, wrapped);
97	            disposers.push(() => window.removeEventListener(event, wrapped));
98	          } else {
99	            target.addEventListener(event, handler as EventListener, opts);
100	            disposers.push(() =>
101	              target.removeEventListener(event, handler as EventListener, opts),
102	            );
103	          }
104	        },
105	
106	        dispatch(event: string, detail?: unknown): void {
107	          window.dispatchEvent(new CustomEvent(event, { detail }));
108	        },
109	
110	        pushEvent(event: string, payload?: object): void {
111	          lv.pushEvent(event, payload ?? {});
112	        },
113	
114	        handleEvent(event: string, handler: (payload: never) => void): void {
115	          const ref = lv.handleEvent(event, handler as (p: unknown) => void);
116	          disposers.push(() => lv.removeHandleEvent(ref));
117	        },
118	
119	        onDestroy(fn: () => void): void {
120	          disposers.push(fn);
121	        },
122	      };
123	
124	      (this as unknown as { _ctxDisposers: Array<() => void> })._ctxDisposers =
125	        disposers;
126	
127	      try {
128	        setup(ctx);
129	      } catch (err) {
130	        for (const dispose of disposers) {
131	          try {
132	            dispose();
133	          } catch {}
134	        }
135	        throw err;
136	      }
137	    },
138	
139	    destroyed(this: ViewHookInternal): void {
140	      const disposers = (
141	        this as unknown as { _ctxDisposers?: Array<() => void> }
142	      )._ctxDisposers;
143	      if (!disposers) return;
144	      for (const dispose of disposers) {
145	        try {
146	          dispose();
147	        } catch (err) {
148	          console.error("hook disposer threw:", err);
149	        }
150	      }
151	    },
152	  };
153	}
