		assert.strictEqual(
			afterSrc,
			sentinelSrc,
			"audio.src must survive a hook destroy/mount cycle — without " +
				"this, sleeping-mobile autoplay re-stalls on wake when LV " +
				"reconnects with a fresh process",
		);
	});

